<script setup lang="ts">import {Run} from '../types/domain';import StatusBadge from './common/StatusBadge.vue';defineProps<{run:Run}>()</script><template><div v-if="run.recovery_state!=='normal'||run.status==='failed'||run.error" :class="['run-recovery',run.status==='failed'?'failed':'active']"><div class="recovery-head"><StatusBadge :status="run.status" :recovery="run.recovery_state"/><span class="eyebrow">RECOVERY / RUN-{{run.id}}</span></div><p v-if="run.recovery_reason">{{run.recovery_reason}}</p><p v-if="run.status==='failed'&&run.error" class="recovery-error"><b>失败原因</b>{{run.error}}</p><dl><div v-if="run.attempts"><dt>接手次数</dt><dd>{{run.attempts}}</dd></div><div v-if="run.recovery_count"><dt>自动恢复</dt><dd>{{run.recovery_count}}次</dd></div><div v-if="run.approved_result_hash"><dt>获批结果</dt><dd>{{run.approved_result_hash.slice(0,12)}}…</dd></div><div v-if="run.result_hash"><dt>结果指纹</dt><dd>{{run.result_hash.slice(0,12)}}…</dd></div></dl><p class="recovery-note">恢复沿用受理时冻结的输入、δ、置换次数与随机种子；已完成结果不会重算或换用另一份文件。</p></div></template>
